}
.btn-white:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }

.btn-dark {
  background: var(--primary);
  color: #fff;
}
.btn-dark:hover { background: var(--primary-light); transform: translateY(-2px); }

.btn-sm { padding: 10px 20px; font-size: 0.875rem; }
