.integration-item:hover { border-color: var(--accent); color: var(--accent); box-shadow: var(--shadow); }
.integration-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

/* ===== Pricing ===== */
.pricing-highlight {
  background: linear-gradient(135deg, var(--primary) 0%, #16213e 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.pricing-highlight::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(67,97,238,0.2) 0%, transparent 70%);
  border-radius: 50%;
}
.pricing-highlight h2 { margin-bottom: 16px; }
.pricing-highlight p { color: rgba(255,255,255,0.8); max-width: 560px; margin: 0 auto 12px; }
.pricing-highlight .price-tag {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--lime);
  margin: 20px 0;
}
.pricing-features {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
  margin: 24px 0 32px;
}
.pricing-feature {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.9);
}
.pricing-feature .check { color: var(--lime); font-weight: 700; }

/* ===== CTA Banner ===== */
.cta-banner {
  background: linear-gradient(135deg, var(--accent) 0%, #6366f1 100%);
  padding: 80px 0;
  text-align: center;
  color: #fff;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -60%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%);
  border-radius: 50%;
}
.cta-banner .container { position: relative; z-index: 1; }
.cta-banner h2 { margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.85); margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Feature Sections (3-col) ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}
.feature-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.feature-card-icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.375rem;
  margin-bottom: 20px;
}
.feature-card h3 { margin-bottom: 12px; }
.feature-card p { font-size: 0.9375rem; }

/* ===== Tools Grid ===== */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}
.tool-category h4 { margin-bottom: 16px; color: var(--accent); }
.tool-category ul { list-style: none; }
.tool-category li {
  padding: 8px 0;
  font-size: 0.9375rem;
  color: var(--text-light);
  display: flex;
  align-items: center;
  gap: 8px;
}
.tool-category li::before {
  content: '+';
  color: var(--accent);
  font-weight: 700;
}

/* ===== Steps ===== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  counter-reset: step;
}
.step-card {
  position: relative;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  counter-increment: step;
}
.step-card::before {
  content: counter(step);
  position: absolute;
  top: -16px;
  left: 28px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.125rem;
}
.step-card h3 { margin-bottom: 12px; margin-top: 8px; }
.step-card p { font-size: 0.9375rem; }

/* ===== Resources ===== */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.resource-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.resource-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.resource-card h3 { margin-bottom: 12px; }
.resource-card p { font-size: 0.9375rem; margin-bottom: 16px; }
.resource-card .card-link { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; font-size: 0.875rem; color: var(--accent); }

/* ===== Spotlight ===== */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.spotlight-card {
  background: #fff;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.spotlight-img {
  height: 180px;
  background: linear-gradient(135deg, var(--accent-light) 0%, #e8faf8 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.spotlight-body { padding: 24px; }
.spotlight-body h3 { margin-bottom: 8px; }
.spotlight-body p { font-size: 0.9375rem; }

/* ===== File Types Grid ===== */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 16px;
}
.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.file-type-item:hover { border-color: var(--accent); box-shadow: var(--shadow); }
.file-type-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
}

/* ===== Membership Stats ===== */
.membership-highlight {
  background: linear-gradient(135deg, #fff8e6, #fff0f0);
  border-radius: var(--radius-lg);
  padding: 48px;
  text-align: center;
}
.membership-stat { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; color: var(--coral); margin-bottom: 12px; }

/* ===== Social Proof ===== */
.social-proof { text-align: center; }
.social-proof-text { font-size: 1.25rem; font-weight: 600; color: var(--text); margin-bottom: 8px; }

/* ===== Footer ===== */
.footer {
  background: var(--bg-dark);
  color: rgba(255,255,255,0.8);
  padding: 80px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .nav-logo { color: #fff; margin-bottom: 16px; }
.footer-brand p { font-size: 0.9375rem; max-width: 280px; }
.footer-col h4 { color: #fff; margin-bottom: 20px; font-size: 0.9375rem; }
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { font-size: 0.875rem; color: rgba(255,255,255,0.6); transition: color var(--transition); }
.footer-col a:hover { color: var(--lime); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

/* ===== AI Section ===== */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
  margin-top: 32px;
}
.ai-feature-item {
  padding: 16px;
  background: rgba(255,255,255,0.06);
  border-radius: var(--radius);
  border: 1px solid rgba(255,255,255,0.1);
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.85);
  transition: all var(--transition);
}
.ai-feature-item:hover { background: rgba(255,255,255,0.1); border-color: var(--lime); }

/* ===== Global Scale ===== */
.global-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.global-map {
  background: var(--bg-alt);
  border-radius: var(--radius-lg);
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 300px;
  font-size: 5rem;
}

/* ===== Animations ===== */
.animate-in {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.animate-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Mobile Nav ===== */
.mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(255,255,255,0.98);
  backdrop-filter: blur(12px);
  z-index: 999;
  padding: 32px 24px;
}
.mobile-menu.open { display: block; }
.mobile-menu .nav-links { flex-direction: column; gap: 24px; }
.mobile-menu .nav-links a { font-size: 1.125rem; }
.mobile-menu .nav-cta { margin-top: 32px; flex-direction: column; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .global-content { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }
  .hero { padding: 110px 0 60px; }
  .section { padding: 64px 0; }
  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .products-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .tab-buttons { justify-content: flex-start; overflow-x: auto; flex-wrap: nowrap; padding-bottom: 8px; }
  .testimonial-card { flex: 0 0 300px; }
  .pricing-highlight { padding: 40px 24px; }
  .footer-grid { grid-template-columns: 1fr; gap: 24px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .steps-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .mockup-grid-3 { grid-template-columns: 1fr; }
  .hero-tabs { width: 100%; justify-content: center; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .file-types-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .tools-grid { grid-template-columns: 1fr; }
  .hero-buttons { flex-direction: column; }
  .hero-buttons .btn { width: 100%; justify-content: center; }
  .integrations-grid { grid-template-columns: 1fr; }
}
