/* ===== LearnForge Global Styles ===== */
:root {
  --primary: #1a1a2e;
  --primary-light: #16213e;
  --accent: #4361ee;
  --accent-hover: #3a56d4;
  --accent-light: #eef1ff;
  --coral: #ff6b6b;
  --green: #2ec4b6;
  --lime: #E6FF32;
  --bg: #ffffff;
  --bg-alt: #f8f9fc;
  --bg-dark: #0a0a1a;
  --text: #1a1a2e;
  --text-light: #6b7280;
  --text-white: #ffffff;
  --border: #e5e7eb;
  --radius: 12px;
  --radius-lg: 20px;
  --shadow: 0 4px 24px rgba(0,0,0,0.06);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.1);
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }

a { text-decoration: none; color: inherit; transition: color var(--transition); }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Typography ===== */
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); font-weight: 700; line-height: 1.15; letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); font-weight: 700; line-height: 1.3; }
h4 { font-size: 1.125rem; font-weight: 600; line-height: 1.4; }
p { font-size: 1.0625rem; color: var(--text-light); }

.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  margin-bottom: 12px;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 1rem;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
  box-shadow: 0 4px 16px rgba(67,97,238,0.3);
}
.btn-primary:hover { background: var(--accent-hover); transform: translateY(-2px); box-shadow: 0 6px 24px rgba(67,97,238,0.4); }

.btn-secondary {
  background: transparent;
  color: var(--text);
  border: 2px solid var(--border);
}
.btn-secondary:hover { border-color: var(--accent); color: var(--accent); }

.btn-white {
  background: #fff;
  color: var(--primary);
  box-shadow: var(--shadow);
}
.btn-white:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }

.btn-dark {
  background: var(--primary);
  color: #fff;
}
.btn-dark:hover { background: var(--primary-light); transform: translateY(-2px); }

.btn-sm { padding: 10px 20px; font-size: 0.875rem; }
.btn-lg { padding: 18px 36px; font-size: 1.125rem; }

/* ===== Navigation ===== */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow var(--transition);
}
.navbar.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-logo span { color: var(--accent); }

.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links a { font-weight: 500; font-size: 0.9375rem; color: var(--text-light); transition: color var(--transition); }
.nav-links a:hover, .nav-links a.active { color: var(--accent); }

.nav-cta { display: flex; align-items: center; gap: 12px; }

.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; padding: 8px; background: none; border: none; }
.hamburger span { display: block; width: 24px; height: 2px; background: var(--text); border-radius: 2px; transition: all var(--transition); }

/* ===== Hero ===== */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(135deg, #f8f9fc 0%, #eef1ff 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(67,97,238,0.08) 0%, transparent 70%);
  border-radius: 50%;
}
.hero .container { position: relative; z-index: 1; }
.hero h1 { margin-bottom: 20px; max-width: 720px; }
.hero p { font-size: 1.25rem; max-width: 600px; margin-bottom: 32px; }
.hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }
.hero-content { max-width: 640px; }

/* ===== Hero Tabs (Home) ===== */
.hero-tabs {
  display: flex;
  gap: 4px;
  background: var(--bg);
  border-radius: 50px;
  padding: 4px;
  margin-bottom: 32px;
  width: fit-content;
  box-shadow: var(--shadow);
}
.hero-tab {
  padding: 10px 24px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  transition: all var(--transition);
  border: none;
  background: transparent;
  color: var(--text-light);
}
.hero-tab.active { background: var(--accent); color: #fff; }
.hero-tab:not(.active):hover { color: var(--accent); }

.hero-preview {
  margin-top: 48px;
  background: var(--bg);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  border: 1px solid var(--border);
}
.hero-preview-content {
  padding: 32px;
  min-height: 320px;
  display: none;
}
.hero-preview-content.active { display: block; }

.preview-mockup {
  background: var(--bg-alt);
  border-radius: var(--radius);
  padding: 24px;
  min-height: 260px;
}
.mockup-header { display: flex; align-items: center; gap: 12px; margin-bottom: 20px; padding-bottom: 16px; border-bottom: 1px solid var(--border); }
.mockup-dot { width: 10px; height: 10px; border-radius: 50%; }
.mockup-dot.red { background: #ff5f57; }
.mockup-dot.yellow { background: #ffbd2e; }
.mockup-dot.green { background: #28c840; }
.mockup-nav { display: flex; gap: 16px; margin-left: auto; }
.mockup-nav span { width: 60px; height: 8px; border-radius: 4px; background: var(--border); }
.mockup-body { display: grid; gap: 16px; }
.mockup-card {
  background: #fff;
  border-radius: var(--radius);
  padding: 20px;
  border: 1px solid var(--border);
}
.mockup-bar { height: 10px; background: var(--border); border-radius: 5px; margin: 8px 0; }
.mockup-bar.short { width: 60%; }
.mockup-bar.accent { background: var(--accent); width: 40%; }
.mockup-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.mockup-stat { text-align: center; padding: 16px; background: #fff; border-radius: var(--radius); border: 1px solid var(--border); }
.mockup-stat .val { font-size: 1.5rem; font-weight: 800; color: var(--accent); }
.mockup-stat .lbl { font-size: 0.75rem; color: var(--text-light); margin-top: 4px; }

/* ===== Stats Bar ===== */
.stats-bar {
  padding: 48px 0;
  background: var(--primary);
  color: #fff;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}
.stat-item .stat-number { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; color: var(--lime); }
.stat-item .stat-label { font-size: 1rem; color: rgba(255,255,255,0.75); margin-top: 4px; }

/* ===== Section Padding ===== */
.section { padding: 96px 0; }
.section-alt { background: var(--bg-alt); }
.section-dark { background: var(--bg-dark); color: #fff; }
.section-dark p { color: rgba(255,255,255,0.7); }
.section-dark .section-label { color: var(--lime); }

.section-header { text-align: center; max-width: 640px; margin: 0 auto 56px; }
.section-header p { margin-top: 16px; }

/* ===== Product Cards ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}
.product-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--accent);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.product-card:hover::before { transform: scaleX(1); }
.product-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}
.product-icon.courses { background: #eef1ff; color: var(--accent); }
.product-icon.coaching { background: #fff0f0; color: var(--coral); }
.product-icon.downloads { background: #e8faf8; color: var(--green); }
.product-icon.memberships { background: #fff8e6; color: #f59e0b; }
.product-card h3 { margin-bottom: 12px; }
.product-card p { font-size: 0.9375rem; }
.product-card .card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 20px;
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--accent);
}
.product-card .card-link:hover { gap: 10px; }

/* ===== Why Choose Us Tabs ===== */
.tabs-container { margin-top: 32px; }
.tab-buttons {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 32px;
  justify-content: center;
}
.tab-btn {
  padding: 12px 24px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  border: 2px solid var(--border);
  background: transparent;
  color: var(--text-light);
  transition: all var(--transition);
}
.tab-btn.active { background: var(--accent); border-color: var(--accent); color: #fff; }
.tab-btn:not(.active):hover { border-color: var(--accent); color: var(--accent); }

.tab-content { display: none; animation: fadeUp 0.4s ease; }
.tab-content.active { display: block; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.features-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  list-style: none;
}
.feature-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 20px;
  background: var(--bg);
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.feature-item:hover { border-color: var(--accent); box-shadow: var(--shadow); }
.feature-check {
  width: 28px;
  height: 28px;
  min-width: 28px;
  border-radius: 50%;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 700;
}

/* ===== Testimonials ===== */
.testimonials-section { position: relative; overflow: hidden; }
.testimonials-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 8px 0;
}
.testimonials-track::-webkit-scrollbar { display: none; }
.testimonial-card {
  flex: 0 0 360px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.testimonial-card:hover { box-shadow: var(--shadow-lg); }
.testimonial-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 50px;
  background: var(--accent-light);
  color: var(--accent);
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: 16px;
}
.testimonial-card blockquote {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text);
  margin-bottom: 20px;
  font-style: italic;
}
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.author-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
}
.author-info .name { font-weight: 600; font-size: 0.9375rem; }
.author-info .role { font-size: 0.8125rem; color: var(--text-light); }

.carousel-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-top: 32px;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--border);
  background: #fff;
  color: var(--text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  transition: all var(--transition);
}
.carousel-btn:hover { border-color: var(--accent); color: var(--accent); }

/* ===== FAQ ===== */
.faq-list { max-width: 720px; margin: 0 auto; }
.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 12px;
  overflow: hidden;
  transition: all var(--transition);
}
.faq-item:hover { border-color: var(--accent); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  cursor: pointer;
  font-weight: 600;
  font-size: 1rem;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  color: var(--text);
  transition: color var(--transition);
}
.faq-question:hover { color: var(--accent); }
.faq-icon {
  font-size: 1.25rem;
  transition: transform var(--transition);
  color: var(--accent);
  min-width: 24px;
  text-align: center;
}
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer-inner { padding: 0 24px 20px; color: var(--text-light); line-height: 1.7; }

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
}
.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px 16px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--text-light);
  transition: all var(--transition);
}
.integration-item:hover { border-color: var(--accent); color: var(--accent); box-shadow: var(--shadow); }
.integration-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

/* ===== Pricing ===== */
.pricing-highlight {
  background: linear-gradient(135deg, var(--primary) 0%, #16213e 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.pricing-highlight::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(67,97,238,0.2) 0%, transparent 70%);
  border-radius: 50%;
}
.pricing-highlight h2 { margin-bottom: 16px; }
.pricing-highlight p { color: rgba(255,255,255,0.8); max-width: 560px; margin: 0 auto 12px; }
.pricing-highlight .price-tag {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--lime);
  margin: 20px 0;
}
.pricing-features {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
  margin: 24px 0 32px;
}
.pricing-feature {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.9);
}
.pricing-feature .check { color: var(--lime); font-weight: 700; }

/* ===== CTA Banner ===== */
.cta-banner {
  background: linear-gradient(135deg, var(--accent) 0%, #6366f1 100%);
  padding: 80px 0;
  text-align: center;
  color: #fff;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -60%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%);
  border-radius: 50%;
}
.cta-banner .container { position: relative; z-index: 1; }
.cta-banner h2 { margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.85); margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Feature Sections (3-col) ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}
.feature-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.feature-card-icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.375rem;
  margin-bottom: 20px;
}
.feature-card h3 { margin-bottom: 12px; }
.feature-card p { font-size: 0.9375rem; }

/* ===== Tools Grid ===== */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}
.tool-category h4 { margin-bottom: 16px; color: var(--accent); }
.tool-category ul { list-style: none; }
.tool-category li {
  padding: 8px 0;
  font-size: 0.9375rem;
  color: var(--text-light);
  display: flex;
  align-items: center;
  gap: 8px;
}
.tool-category li::before {
  content: '+';
  color: var(--accent);
  font-weight: 700;
}

/* ===== Steps ===== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  counter-reset: step;
}
.step-card {
  position: relative;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  counter-increment: step;
}
.step-card::before {
  content: counter(step);
  position: absolute;
  top: -16px;
  left: 28px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.125rem;
}
.step-card h3 { margin-bottom: 12px; margin-top: 8px; }
.step-card p { font-size: 0.9375rem; }

/* ===== Resources ===== */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.resource-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.resource-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.resource-card h3 { margin-bottom: 12px; }
.resource-card p { font-size: 0.9375rem; margin-bottom: 16px; }
.resource-card .card-link { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; font-size: 0.875rem; color: var(--accent); }

/* ===== Spotlight ===== */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.spotlight-card {
  background: #fff;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.spotlight-img {
  height: 180px;
  background: linear-gradient(135deg, var(--accent-light) 0%, #e8faf8 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.spotlight-body { padding: 24px; }
.spotlight-body h3 { margin-bottom: 8px; }
.spotlight-body p { font-size: 0.9375rem; }

/* ===== File Types Grid ===== */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 16px;
}
.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.file-type-item:hover { border-color: var(--accent); box-shadow: var(--shadow); }
.file-type-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
}

/* ===== Membership Stats ===== */
.membership-highlight {
  background: linear-gradient(135deg, #fff8e6, #fff0f0);
  border-radius: var(--radius-lg);
  padding: 48px;
  text-align: center;
}
.membership-stat { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; color: var(--coral); margin-bottom: 12px; }

/* ===== Social Proof ===== */
.social-proof { text-align: center; }
.social-proof-text { font-size: 1.25rem; font-weight: 600; color: var(--text); margin-bottom: 8px; }

/* ===== Footer ===== */
.footer {
  background: var(--bg-dark);
  color: rgba(255,255,255,0.8);
  padding: 80px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .nav-logo { color: #fff; margin-bottom: 16px; }
.footer-brand p { font-size: 0.9375rem; max-width: 280px; }
.footer-col h4 { color: #fff; margin-bottom: 20px; font-size: 0.9375rem; }
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { font-size: 0.875rem; color: rgba(255,255,255,0.6); transition: color var(--transition); }
.footer-col a:hover { color: var(--lime); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

/* ===== AI Section ===== */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
  margin-top: 32px;
}
.ai-feature-item {
  padding: 16px;
  background: rgba(255,255,255,0.06);
  border-radius: var(--radius);
  border: 1px solid rgba(255,255,255,0.1);
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.85);
  transition: all var(--transition);
}
.ai-feature-item:hover { background: rgba(255,255,255,0.1); border-color: var(--lime); }

/* ===== Global Scale ===== */
.global-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.global-map {
  background: var(--bg-alt);
  border-radius: var(--radius-lg);
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 300px;
  font-size: 5rem;
}

/* ===== Animations ===== */
.animate-in {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.animate-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Mobile Nav ===== */
.mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(255,255,255,0.98);
  backdrop-filter: blur(12px);
  z-index: 999;
  padding: 32px 24px;
}
.mobile-menu.open { display: block; }
.mobile-menu .nav-links { flex-direction: column; gap: 24px; }
.mobile-menu .nav-links a { font-size: 1.125rem; }
.mobile-menu .nav-cta { margin-top: 32px; flex-direction: column; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .global-content { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }
  .hero { padding: 110px 0 60px; }
  .section { padding: 64px 0; }
  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .products-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .tab-buttons { justify-content: flex-start; overflow-x: auto; flex-wrap: nowrap; padding-bottom: 8px; }
  .testimonial-card { flex: 0 0 300px; }
  .pricing-highlight { padding: 40px 24px; }
  .footer-grid { grid-template-columns: 1fr; gap: 24px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .steps-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .mockup-grid-3 { grid-template-columns: 1fr; }
  .hero-tabs { width: 100%; justify-content: center; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .file-types-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .tools-grid { grid-template-columns: 1fr; }
  .hero-buttons { flex-direction: column; }
  .hero-buttons .btn { width: 100%; justify-content: center; }
  .integrations-grid { grid-template-columns: 1fr; }
}

/* ===== LearnForge Global Styles ===== */
:root {
  --primary: #1a1a2e;
  --primary-light: #16213e;
  --accent: #4361ee;
  --accent-hover: #3a56d4;
  --accent-light: #eef1ff;
  --coral: #ff6b6b;
  --green: #2ec4b6;
  --lime: #E6FF32;
  --bg: #ffffff;
  --bg-alt: #f8f9fc;
  --bg-dark: #0a0a1a;
  --text: #1a1a2e;
  --text-light: #6b7280;
  --text-white: #ffffff;
  --border: #e5e7eb;
  --radius: 12px;
  --radius-lg: 20px;
  --shadow: 0 4px 24px rgba(0,0,0,0.06);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.1);
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }

a { text-decoration: none; color: inherit; transition: color var(--transition); }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Typography ===== */
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); font-weight: 700; line-height: 1.15; letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); font-weight: 700; line-height: 1.3; }
h4 { font-size: 1.125rem; font-weight: 600; line-height: 1.4; }
p { font-size: 1.0625rem; color: var(--text-light); }

.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  margin-bottom: 12px;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 1rem;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
  box-shadow: 0 4px 16px rgba(67,97,238,0.3);
}
.btn-primary:hover { background: var(--accent-hover); transform: translateY(-2px); box-shadow: 0 6px 24px rgba(67,97,238,0.4); }

.btn-secondary {
  background: transparent;
  color: var(--text);
  border: 2px solid var(--border);
}
.btn-secondary:hover { border-color: var(--accent); color: var(--accent); }

.btn-white {
  background: #fff;
  color: var(--primary);
  box-shadow: var(--shadow);
}
.btn-white:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }

.btn-dark {
  background: var(--primary);
  color: #fff;
}
.btn-dark:hover { background: var(--primary-light); transform: translateY(-2px); }

.btn-sm { padding: 10px 20px; font-size: 0.875rem; }
.btn-lg { padding: 18px 36px; font-size: 1.125rem; }

/* ===== Navigation ===== */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow var(--transition);
}
.navbar.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-logo span { color: var(--accent); }

.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links a { font-weight: 500; font-size: 0.9375rem; color: var(--text-light); transition: color var(--transition); }
.nav-links a:hover, .nav-links a.active { color: var(--accent); }

.nav-cta { display: flex; align-items: center; gap: 12px; }

.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; padding: 8px; background: none; border: none; }
.hamburger span { display: block; width: 24px; height: 2px; background: var(--text); border-radius: 2px; transition: all var(--transition); }

/* ===== Hero ===== */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(135deg, #f8f9fc 0%, #eef1ff 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(67,97,238,0.08) 0%, transparent 70%);
  border-radius: 50%;
}
.hero .container { position: relative; z-index: 1; }
.hero h1 { margin-bottom: 20px; max-width: 720px; }
.hero p { font-size: 1.25rem; max-width: 600px; margin-bottom: 32px; }
.hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }
.hero-content { max-width: 640px; }

/* ===== Hero Tabs (Home) ===== */
.hero-tabs {
  display: flex;
  gap: 4px;
  background: var(--bg);
  border-radius: 50px;
  padding: 4px;
  margin-bottom: 32px;
  width: fit-content;
  box-shadow: var(--shadow);
}
.hero-tab {
  padding: 10px 24px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  transition: all var(--transition);
  border: none;
  background: transparent;
  color: var(--text-light);
}
.hero-tab.active { background: var(--accent); color: #fff; }
.hero-tab:not(.active):hover { color: var(--accent); }

.hero-preview {
  margin-top: 48px;
  background: var(--bg);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  border: 1px solid var(--border);
}
.hero-preview-content {
  padding: 32px;
  min-height: 320px;
  display: none;
}
.hero-preview-content.active { display: block; }

.preview-mockup {
  background: var(--bg-alt);
  border-radius: var(--radius);
  padding: 24px;
  min-height: 260px;
}
.mockup-header { display: flex; align-items: center; gap: 12px; margin-bottom: 20px; padding-bottom: 16px; border-bottom: 1px solid var(--border); }
.mockup-dot { width: 10px; height: 10px; border-radius: 50%; }
.mockup-dot.red { background: #ff5f57; }
.mockup-dot.yellow { background: #ffbd2e; }
.mockup-dot.green { background: #28c840; }
.mockup-nav { display: flex; gap: 16px; margin-left: auto; }
.mockup-nav span { width: 60px; height: 8px; border-radius: 4px; background: var(--border); }
.mockup-body { display: grid; gap: 16px; }
.mockup-card {
  background: #fff;
  border-radius: var(--radius);
  padding: 20px;
  border: 1px solid var(--border);
}
.mockup-bar { height: 10px; background: var(--border); border-radius: 5px; margin: 8px 0; }
.mockup-bar.short { width: 60%; }
.mockup-bar.accent { background: var(--accent); width: 40%; }
.mockup-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.mockup-stat { text-align: center; padding: 16px; background: #fff; border-radius: var(--radius); border: 1px solid var(--border); }
.mockup-stat .val { font-size: 1.5rem; font-weight: 800; color: var(--accent); }
.mockup-stat .lbl { font-size: 0.75rem; color: var(--text-light); margin-top: 4px; }

/* ===== Stats Bar ===== */
.stats-bar {
  padding: 48px 0;
  background: var(--primary);
  color: #fff;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}
.stat-item .stat-number { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; color: var(--lime); }
.stat-item .stat-label { font-size: 1rem; color: rgba(255,255,255,0.75); margin-top: 4px; }

/* ===== Section Padding ===== */
.section { padding: 96px 0; }
.section-alt { background: var(--bg-alt); }
.section-dark { background: var(--bg-dark); color: #fff; }
.section-dark p { color: rgba(255,255,255,0.7); }
.section-dark .section-label { color: var(--lime); }

.section-header { text-align: center; max-width: 640px; margin: 0 auto 56px; }
.section-header p { margin-top: 16px; }

/* ===== Product Cards ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}
.product-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--accent);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.product-card:hover::before { transform: scaleX(1); }
.product-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}
.product-icon.courses { background: #eef1ff; color: var(--accent); }
.product-icon.coaching { background: #fff0f0; color: var(--coral); }
.product-icon.downloads { background: #e8faf8; color: var(--green); }
.product-icon.memberships { background: #fff8e6; color: #f59e0b; }
.product-card h3 { margin-bottom: 12px; }
.product-card p { font-size: 0.9375rem; }
.product-card .card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 20px;
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--accent);
}
.product-card .card-link:hover { gap: 10px; }

/* ===== Why Choose Us Tabs ===== */
.tabs-container { margin-top: 32px; }
.tab-buttons {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 32px;
  justify-content: center;
}
.tab-btn {
  padding: 12px 24px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  border: 2px solid var(--border);
  background: transparent;
  color: var(--text-light);
  transition: all var(--transition);
}
.tab-btn.active { background: var(--accent); border-color: var(--accent); color: #fff; }
.tab-btn:not(.active):hover { border-color: var(--accent); color: var(--accent); }

.tab-content { display: none; animation: fadeUp 0.4s ease; }
.tab-content.active { display: block; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.features-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  list-style: none;
}
.feature-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 20px;
  background: var(--bg);
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.feature-item:hover { border-color: var(--accent); box-shadow: var(--shadow); }
.feature-check {
  width: 28px;
  height: 28px;
  min-width: 28px;
  border-radius: 50%;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 700;
}

/* ===== Testimonials ===== */
.testimonials-section { position: relative; overflow: hidden; }
.testimonials-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 8px 0;
}
.testimonials-track::-webkit-scrollbar { display: none; }
.testimonial-card {
  flex: 0 0 360px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.testimonial-card:hover { box-shadow: var(--shadow-lg); }
.testimonial-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 50px;
  background: var(--accent-light);
  color: var(--accent);
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: 16px;
}
.testimonial-card blockquote {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text);
  margin-bottom: 20px;
  font-style: italic;
}
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.author-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
}
.author-info .name { font-weight: 600; font-size: 0.9375rem; }
.author-info .role { font-size: 0.8125rem; color: var(--text-light); }

.carousel-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-top: 32px;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--border);
  background: #fff;
  color: var(--text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  transition: all var(--transition);
}
.carousel-btn:hover { border-color: var(--accent); color: var(--accent); }

/* ===== FAQ ===== */
.faq-list { max-width: 720px; margin: 0 auto; }
.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 12px;
  overflow: hidden;
  transition: all var(--transition);
}
.faq-item:hover { border-color: var(--accent); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  cursor: pointer;
  font-weight: 600;
  font-size: 1rem;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  color: var(--text);
  transition: color var(--transition);
}
.faq-question:hover { color: var(--accent); }
.faq-icon {
  font-size: 1.25rem;
  transition: transform var(--transition);
  color: var(--accent);
  min-width: 24px;
  text-align: center;
}
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer-inner { padding: 0 24px 20px; color: var(--text-light); line-height: 1.7; }

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
}
.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px 16px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--text-light);
  transition: all var(--transition);
}
.integration-item:hover { border-color: var(--accent); color: var(--accent); box-shadow: var(--shadow); }
.integration-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

/* ===== Pricing ===== */
.pricing-highlight {
  background: linear-gradient(135deg, var(--primary) 0%, #16213e 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.pricing-highlight::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(67,97,238,0.2) 0%, transparent 70%);
  border-radius: 50%;
}
.pricing-highlight h2 { margin-bottom: 16px; }
.pricing-highlight p { color: rgba(255,255,255,0.8); max-width: 560px; margin: 0 auto 12px; }
.pricing-highlight .price-tag {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--lime);
  margin: 20px 0;
}
.pricing-features {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
  margin: 24px 0 32px;
}
.pricing-feature {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.9);
}
.pricing-feature .check { color: var(--lime); font-weight: 700; }

/* ===== CTA Banner ===== */
.cta-banner {
  background: linear-gradient(135deg, var(--accent) 0%, #6366f1 100%);
  padding: 80px 0;
  text-align: center;
  color: #fff;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -60%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%);
  border-radius: 50%;
}
.cta-banner .container { position: relative; z-index: 1; }
.cta-banner h2 { margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.85); margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Feature Sections (3-col) ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}
.feature-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.feature-card-icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.375rem;
  margin-bottom: 20px;
}
.feature-card h3 { margin-bottom: 12px; }
.feature-card p { font-size: 0.9375rem; }

/* ===== Tools Grid ===== */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}
.tool-category h4 { margin-bottom: 16px; color: var(--accent); }
.tool-category ul { list-style: none; }
.tool-category li {
  padding: 8px 0;
  font-size: 0.9375rem;
  color: var(--text-light);
  display: flex;
  align-items: center;
  gap: 8px;
}
.tool-category li::before {
  content: '+';
  color: var(--accent);
  font-weight: 700;
}

/* ===== Steps ===== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  counter-reset: step;
}
.step-card {
  position: relative;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  counter-increment: step;
}
.step-card::before {
  content: counter(step);
  position: absolute;
  top: -16px;
  left: 28px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.125rem;
}
.step-card h3 { margin-bottom: 12px; margin-top: 8px; }
.step-card p { font-size: 0.9375rem; }

/* ===== Resources ===== */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.resource-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.resource-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.resource-card h3 { margin-bottom: 12px; }
.resource-card p { font-size: 0.9375rem; margin-bottom: 16px; }
.resource-card .card-link { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; font-size: 0.875rem; color: var(--accent); }

/* ===== Spotlight ===== */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.spotlight-card {
  background: #fff;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.spotlight-img {
  height: 180px;
  background: linear-gradient(135deg, var(--accent-light) 0%, #e8faf8 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.spotlight-body { padding: 24px; }
.spotlight-body h3 { margin-bottom: 8px; }
.spotlight-body p { font-size: 0.9375rem; }

/* ===== File Types Grid ===== */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 16px;
}
.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.file-type-item:hover { border-color: var(--accent); box-shadow: var(--shadow); }
.file-type-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
}

/* ===== Membership Stats ===== */
.membership-highlight {
  background: linear-gradient(135deg, #fff8e6, #fff0f0);
  border-radius: var(--radius-lg);
  padding: 48px;
  text-align: center;
}
.membership-stat { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; color: var(--coral); margin-bottom: 12px; }

/* ===== Social Proof ===== */
.social-proof { text-align: center; }
.social-proof-text { font-size: 1.25rem; font-weight: 600; color: var(--text); margin-bottom: 8px; }

/* ===== Footer ===== */
.footer {
  background: var(--bg-dark);
  color: rgba(255,255,255,0.8);
  padding: 80px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .nav-logo { color: #fff; margin-bottom: 16px; }
.footer-brand p { font-size: 0.9375rem; max-width: 280px; }
.footer-col h4 { color: #fff; margin-bottom: 20px; font-size: 0.9375rem; }
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { font-size: 0.875rem; color: rgba(255,255,255,0.6); transition: color var(--transition); }
.footer-col a:hover { color: var(--lime); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

/* ===== AI Section ===== */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
  margin-top: 32px;
}
.ai-feature-item {
  padding: 16px;
  background: rgba(255,255,255,0.06);
  border-radius: var(--radius);
  border: 1px solid rgba(255,255,255,0.1);
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.85);
  transition: all var(--transition);
}
.ai-feature-item:hover { background: rgba(255,255,255,0.1); border-color: var(--lime); }

/* ===== Global Scale ===== */
.global-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.global-map {
  background: var(--bg-alt);
  border-radius: var(--radius-lg);
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 300px;
  font-size: 5rem;
}

/* ===== Animations ===== */
.animate-in {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.animate-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Mobile Nav ===== */
.mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(255,255,255,0.98);
  backdrop-filter: blur(12px);
  z-index: 999;
  padding: 32px 24px;
}
.mobile-menu.open { display: block; }
.mobile-menu .nav-links { flex-direction: column; gap: 24px; }
.mobile-menu .nav-links a { font-size: 1.125rem; }
.mobile-menu .nav-cta { margin-top: 32px; flex-direction: column; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .global-content { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }
  .hero { padding: 110px 0 60px; }
  .section { padding: 64px 0; }
  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .products-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .tab-buttons { justify-content: flex-start; overflow-x: auto; flex-wrap: nowrap; padding-bottom: 8px; }
  .testimonial-card { flex: 0 0 300px; }
  .pricing-highlight { padding: 40px 24px; }
  .footer-grid { grid-template-columns: 1fr; gap: 24px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .steps-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .mockup-grid-3 { grid-template-columns: 1fr; }
  .hero-tabs { width: 100%; justify-content: center; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .file-types-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .tools-grid { grid-template-columns: 1fr; }
  .hero-buttons { flex-direction: column; }
  .hero-buttons .btn { width: 100%; justify-content: center; }
  .integrations-grid { grid-template-columns: 1fr; }
}

raw_arguments.content:
/* ===== LearnForge Global Styles ===== */
:root {
  --primary: #1a1a2e;
  --primary-light: #16213e;
  --accent: #4361ee;
  --accent-hover: #3a56d4;
  --accent-light: #eef1ff;
  --coral: #ff6b6b;
  --green: #2ec4b6;
  --lime: #E6FF32;
  --bg: #ffffff;
  --bg-alt: #f8f9fc;
  --bg-dark: #0a0a1a;
  --text: #1a1a2e;
  --text-light: #6b7280;
  --text-white: #ffffff;
  --border: #e5e7eb;
  --radius: 12px;
  --radius-lg: 20px;
  --shadow: 0 4px 24px rgba(0,0,0,0.06);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.1);
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }

a { text-decoration: none; color: inherit; transition: color var(--transition); }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Typography ===== */
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); font-weight: 700; line-height: 1.15; letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); font-weight: 700; line-height: 1.3; }
h4 { font-size: 1.125rem; font-weight: 600; line-height: 1.4; }
p { font-size: 1.0625rem; color: var(--text-light); }

.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  margin-bottom: 12px;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 1rem;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
  box-shadow: 0 4px 16px rgba(67,97,238,0.3);
}
.btn-primary:hover { background: var(--accent-hover); transform: translateY(-2px); box-shadow: 0 6px 24px rgba(67,97,238,0.4); }

.btn-secondary {
  background: transparent;
  color: var(--text);
  border: 2px solid var(--border);
}
.btn-secondary:hover { border-color: var(--accent); color: var(--accent); }

.btn-white {
  background: #fff;
  color: var(--primary);
  box-shadow: var(--shadow);
}
.btn-white:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }

.btn-dark {
  background: var(--primary);
  color: #fff;
}
.btn-dark:hover { background: var(--primary-light); transform: translateY(-2px); }

.btn-sm { padding: 10px 20px; font-size: 0.875rem; }
.btn-lg { padding: 18px 36px; font-size: 1.125rem; }

/* ===== Navigation ===== */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow var(--transition);
}
.navbar.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-logo span { color: var(--accent); }

.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links a { font-weight: 500; font-size: 0.9375rem; color: var(--text-light); transition: color var(--transition); }
.nav-links a:hover, .nav-links a.active { color: var(--accent); }

.nav-cta { display: flex; align-items: center; gap: 12px; }

.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; padding: 8px; background: none; border: none; }
.hamburger span { display: block; width: 24px; height: 2px; background: var(--text); border-radius: 2px; transition: all var(--transition); }

/* ===== Hero ===== */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(135deg, #f8f9fc 0%, #eef1ff 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(67,97,238,0.08) 0%, transparent 70%);
  border-radius: 50%;
}
.hero .container { position: relative; z-index: 1; }
.hero h1 { margin-bottom: 20px; max-width: 720px; }
.hero p { font-size: 1.25rem; max-width: 600px; margin-bottom: 32px; }
.hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }
.hero-content { max-width: 640px; }

/* ===== Hero Tabs (Home) ===== */
.hero-tabs {
  display: flex;
  gap: 4px;
  background: var(--bg);
  border-radius: 50px;
  padding: 4px;
  margin-bottom: 32px;
  width: fit-content;
  box-shadow: var(--shadow);
}
.hero-tab {
  padding: 10px 24px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  transition: all var(--transition);
  border: none;
  background: transparent;
  color: var(--text-light);
}
.hero-tab.active { background: var(--accent); color: #fff; }
.hero-tab:not(.active):hover { color: var(--accent); }

.hero-preview {
  margin-top: 48px;
  background: var(--bg);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  border: 1px solid var(--border);
}
.hero-preview-content {
  padding: 32px;
  min-height: 320px;
  display: none;
}
.hero-preview-content.active { display: block; }

.preview-mockup {
  background: var(--bg-alt);
  border-radius: var(--radius);
  padding: 24px;
  min-height: 260px;
}
.mockup-header { display: flex; align-items: center; gap: 12px; margin-bottom: 20px; padding-bottom: 16px; border-bottom: 1px solid var(--border); }
.mockup-dot { width: 10px; height: 10px; border-radius: 50%; }
.mockup-dot.red { background: #ff5f57; }
.mockup-dot.yellow { background: #ffbd2e; }
.mockup-dot.green { background: #28c840; }
.mockup-nav { display: flex; gap: 16px; margin-left: auto; }
.mockup-nav span { width: 60px; height: 8px; border-radius: 4px; background: var(--border); }
.mockup-body { display: grid; gap: 16px; }
.mockup-card {
  background: #fff;
  border-radius: var(--radius);
  padding: 20px;
  border: 1px solid var(--border);
}
.mockup-bar { height: 10px; background: var(--border); border-radius: 5px; margin: 8px 0; }
.mockup-bar.short { width: 60%; }
.mockup-bar.accent { background: var(--accent); width: 40%; }
.mockup-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.mockup-stat { text-align: center; padding: 16px; background: #fff; border-radius: var(--radius); border: 1px solid var(--border); }
.mockup-stat .val { font-size: 1.5rem; font-weight: 800; color: var(--accent); }
.mockup-stat .lbl { font-size: 0.75rem; color: var(--text-light); margin-top: 4px; }

/* ===== Stats Bar ===== */
.stats-bar {
  padding: 48px 0;
  background: var(--primary);
  color: #fff;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}
.stat-item .stat-number { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; color: var(--lime); }
.stat-item .stat-label { font-size: 1rem; color: rgba(255,255,255,0.75); margin-top: 4px; }

/* ===== Section Padding ===== */
.section { padding: 96px 0; }
.section-alt { background: var(--bg-alt); }
.section-dark { background: var(--bg-dark); color: #fff; }
.section-dark p { color: rgba(255,255,255,0.7); }
.section-dark .section-label { color: var(--lime); }

.section-header { text-align: center; max-width: 640px; margin: 0 auto 56px; }
.section-header p { margin-top: 16px; }

/* ===== Product Cards ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}
.product-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--accent);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.product-card:hover::before { transform: scaleX(1); }
.product-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}
.product-icon.courses { background: #eef1ff; color: var(--accent); }
.product-icon.coaching { background: #fff0f0; color: var(--coral); }
.product-icon.downloads { background: #e8faf8; color: var(--green); }
.product-icon.memberships { background: #fff8e6; color: #f59e0b; }
.product-card h3 { margin-bottom: 12px; }
.product-card p { font-size: 0.9375rem; }
.product-card .card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 20px;
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--accent);
}
.product-card .card-link:hover { gap: 10px; }

/* ===== Why Choose Us Tabs ===== */
.tabs-container { margin-top: 32px; }
.tab-buttons {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 32px;
  justify-content: center;
}
.tab-btn {
  padding: 12px 24px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  border: 2px solid var(--border);
  background: transparent;
  color: var(--text-light);
  transition: all var(--transition);
}
.tab-btn.active { background: var(--accent); border-color: var(--accent); color: #fff; }
.tab-btn:not(.active):hover { border-color: var(--accent); color: var(--accent); }

.tab-content { display: none; animation: fadeUp 0.4s ease; }
.tab-content.active { display: block; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.features-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  list-style: none;
}
.feature-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 20px;
  background: var(--bg);
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.feature-item:hover { border-color: var(--accent); box-shadow: var(--shadow); }
.feature-check {
  width: 28px;
  height: 28px;
  min-width: 28px;
  border-radius: 50%;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 700;
}

/* ===== Testimonials ===== */
.testimonials-section { position: relative; overflow: hidden; }
.testimonials-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 8px 0;
}
.testimonials-track::-webkit-scrollbar { display: none; }
.testimonial-card {
  flex: 0 0 360px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.testimonial-card:hover { box-shadow: var(--shadow-lg); }
.testimonial-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 50px;
  background: var(--accent-light);
  color: var(--accent);
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: 16px;
}
.testimonial-card blockquote {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text);
  margin-bottom: 20px;
  font-style: italic;
}
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.author-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
}
.author-info .name { font-weight: 600; font-size: 0.9375rem; }
.author-info .role { font-size: 0.8125rem; color: var(--text-light); }

.carousel-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-top: 32px;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--border);
  background: #fff;
  color: var(--text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  transition: all var(--transition);
}
.carousel-btn:hover { border-color: var(--accent); color: var(--accent); }

/* ===== FAQ ===== */
.faq-list { max-width: 720px; margin: 0 auto; }
.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 12px;
  overflow: hidden;
  transition: all var(--transition);
}
.faq-item:hover { border-color: var(--accent); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  cursor: pointer;
  font-weight: 600;
  font-size: 1rem;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  color: var(--text);
  transition: color var(--transition);
}
.faq-question:hover { color: var(--accent); }
.faq-icon {
  font-size: 1.25rem;
  transition: transform var(--transition);
  color: var(--accent);
  min-width: 24px;
  text-align: center;
}
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer-inner { padding: 0 24px 20px; color: var(--text-light); line-height: 1.7; }

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
}
.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px 16px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--text-light);
  transition: all var(--transition);
}
.integration-item:hover { border-color: var(--accent); color: var(--accent); box-shadow: var(--shadow); }
.integration-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

/* ===== Pricing ===== */
.pricing-highlight {
  background: linear-gradient(135deg, var(--primary) 0%, #16213e 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.pricing-highlight::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(67,97,238,0.2) 0%, transparent 70%);
  border-radius: 50%;
}
.pricing-highlight h2 { margin-bottom: 16px; }
.pricing-highlight p { color: rgba(255,255,255,0.8); max-width: 560px; margin: 0 auto 12px; }
.pricing-highlight .price-tag {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--lime);
  margin: 20px 0;
}
.pricing-features {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
  margin: 24px 0 32px;
}
.pricing-feature {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.9);
}
.pricing-feature .check { color: var(--lime); font-weight: 700; }

/* ===== CTA Banner ===== */
.cta-banner {
  background: linear-gradient(135deg, var(--accent) 0%, #6366f1 100%);
  padding: 80px 0;
  text-align: center;
  color: #fff;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -60%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%);
  border-radius: 50%;
}
.cta-banner .container { position: relative; z-index: 1; }
.cta-banner h2 { margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.85); margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ===== Feature Sections (3-col) ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}
.feature-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.feature-card-icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.375rem;
  margin-bottom: 20px;
}
.feature-card h3 { margin-bottom: 12px; }
.feature-card p { font-size: 0.9375rem; }

/* ===== Tools Grid ===== */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}
.tool-category h4 { margin-bottom: 16px; color: var(--accent); }
.tool-category ul { list-style: none; }
.tool-category li {
  padding: 8px 0;
  font-size: 0.9375rem;
  color: var(--text-light);
  display: flex;
  align-items: center;
  gap: 8px;
}
.tool-category li::before {
  content: '+';
  color: var(--accent);
  font-weight: 700;
}

/* ===== Steps ===== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  counter-reset: step;
}
.step-card {
  position: relative;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  counter-increment: step;
}
.step-card::before {
  content: counter(step);
  position: absolute;
  top: -16px;
  left: 28px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.125rem;
}
.step-card h3 { margin-bottom: 12px; margin-top: 8px; }
.step-card p { font-size: 0.9375rem; }

/* ===== Resources ===== */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.resource-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.resource-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.resource-card h3 { margin-bottom: 12px; }
.resource-card p { font-size: 0.9375rem; margin-bottom: 16px; }
.resource-card .card-link { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; font-size: 0.875rem; color: var(--accent); }

/* ===== Spotlight ===== */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.spotlight-card {
  background: #fff;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.spotlight-img {
  height: 180px;
  background: linear-gradient(135deg, var(--accent-light) 0%, #e8faf8 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.spotlight-body { padding: 24px; }
.spotlight-body h3 { margin-bottom: 8px; }
.spotlight-body p { font-size: 0.9375rem; }

/* ===== File Types Grid ===== */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 16px;
}
.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px;
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.file-type-item:hover { border-color: var(--accent); box-shadow: var(--shadow); }
.file-type-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--accent-light);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
}

/* ===== Membership Stats ===== */
.membership-highlight {
  background: linear-gradient(135deg, #fff8e6, #fff0f0);
  border-radius: var(--radius-lg);
  padding: 48px;
  text-align: center;
}
.membership-stat { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; color: var(--coral); margin-bottom: 12px; }

/* ===== Social Proof ===== */
.social-proof { text-align: center; }
.social-proof-text { font-size: 1.25rem; font-weight: 600; color: var(--text); margin-bottom: 8px; }

/* ===== Footer ===== */
.footer {
  background: var(--bg-dark);
  color: rgba(255,255,255,0.8);
  padding: 80px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .nav-logo { color: #fff; margin-bottom: 16px; }
.footer-brand p { font-size: 0.9375rem; max-width: 280px; }
.footer-col h4 { color: #fff; margin-bottom: 20px; font-size: 0.9375rem; }
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { font-size: 0.875rem; color: rgba(255,255,255,0.6); transition: color var(--transition); }
.footer-col a:hover { color: var(--lime); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

/* ===== AI Section ===== */
.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
  margin-top: 32px;
}
.ai-feature-item {
  padding: 16px;
  background: rgba(255,255,255,0.06);
  border-radius: var(--radius);
  border: 1px solid rgba(255,255,255,0.1);
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.85);
  transition: all var(--transition);
}
.ai-feature-item:hover { background: rgba(255,255,255,0.1); border-color: var(--lime); }

/* ===== Global Scale ===== */
.global-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.global-map {
  background: var(--bg-alt);
  border-radius: var(--radius-lg);
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 300px;
  font-size: 5rem;
}

/* ===== Animations ===== */
.animate-in {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.animate-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Mobile Nav ===== */
.mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(255,255,255,0.98);
  backdrop-filter: blur(12px);
  z-index: 999;
  padding: 32px 24px;
}
.mobile-menu.open { display: block; }
.mobile-menu .nav-links { flex-direction: column; gap: 24px; }
.mobile-menu .nav-links a { font-size: 1.125rem; }
.mobile-menu .nav-cta { margin-top: 32px; flex-direction: column; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .global-content { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }
  .hero { padding: 110px 0 60px; }
  .section { padding: 64px 0; }
  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .products-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .tab-buttons { justify-content: flex-start; overflow-x: auto; flex-wrap: nowrap; padding-bottom: 8px; }
  .testimonial-card { flex: 0 0 300px; }
  .pricing-highlight { padding: 40px 24px; }
  .footer-grid { grid-template-columns: 1fr; gap: 24px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .steps-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .mockup-grid-3 { grid-template-columns: 1fr; }
  .hero-tabs { width: 100%; justify-content: center; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .file-types-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .tools-grid { grid-template-columns: 1fr; }
  .hero-buttons { flex-direction: column; }
  .hero-buttons .btn { width: 100%; justify-content: center; }
  .integrations-grid { grid-template-columns: 1fr; }
}

